void
_3ds_utf8_to_cp1251(char *dst, const char *src, size_t dst_sz)
{
    unsigned char *d = (unsigned char *) dst;
    const unsigned char *s = (const unsigned char *) src;
    size_t i = 0;

    if (!dst || !src || dst_sz == 0)
        return;

    while (*s && i + 1 < dst_sz) {
        if (s[0] == 0xD0) {
            if (s[1] >= 0x90 && s[1] <= 0xBF) { /* А..п (CP1251: 0xC0..0xEF) */
                d[i++] = (unsigned char) (s[1] + 0x30);
                s += 2;
            } else if (s[1] == 0x81) { /* Ё (CP1251: 0xA8) */
                d[i++] = 0xA8;
                s += 2;
            } else {
                d[i++] = *s++;
            }
        } else if (s[0] == 0xD1) {
            if (s[1] >= 0x80 && s[1] <= 0x8F) { /* р..я (CP1251: 0xF0..0xFF) */
                d[i++] = (unsigned char) (s[1] + 0x70);
                s += 2;
            } else if (s[1] == 0x91) { /* ё (CP1251: 0xB8) */
                d[i++] = 0xB8;
                s += 2;
            } else {
                d[i++] = *s++;
            }
        } else {
            d[i++] = *s++;
        }
    }
    d[i] = '\0';
}

static void
utf8_to_cp1251(char *dst, const char *src, size_t dst_sz)
{
    _3ds_utf8_to_cp1251(dst, src, dst_sz);
}

void
_3ds_i18n_init(void)
{
    size_t count = sizeof(dictionary) / sizeof(dictionary[0]);
    for (size_t i = 0; i < count; i++) {
        _3ds_utf8_to_cp1251(dictionary[i].ru_cp1251,
                            dictionary[i].ru_utf8,
                            sizeof(dictionary[i].ru_cp1251));
    }
    size_t icount = sizeof(item_dictionary) / sizeof(item_dictionary[0]);
    for (size_t i = 0; i < icount; i++) {
        _3ds_utf8_to_cp1251(item_dictionary[i].ru_cp1251,
                            item_dictionary[i].ru_utf8,
                            sizeof(item_dictionary[i].ru_cp1251));
    }
    size_t mcount = sizeof(monster_dictionary) / sizeof(monster_dictionary[0]);
    for (size_t i = 0; i < mcount; i++) {
        _3ds_utf8_to_cp1251(monster_dictionary[i].ru_cp1251,
                            monster_dictionary[i].ru_utf8,
                            sizeof(monster_dictionary[i].ru_cp1251));
    }
}

int
_3ds_i18n_get_language(void)
{
    return current_lang;
}

void
_3ds_i18n_set_language(int lang)
{
    current_lang = (lang == NH_LANG_RU) ? NH_LANG_RU : NH_LANG_EN;
}

const char *
nh_tr(const char *str)
{
    if (!str || current_lang == NH_LANG_EN)
        return str;

    size_t count = sizeof(dictionary) / sizeof(dictionary[0]);
    for (size_t i = 0; i < count; i++) {
        if (!strcmp(str, dictionary[i].en)) {
            return dictionary[i].ru_cp1251;
        }
    }
    size_t icount = sizeof(item_dictionary) / sizeof(item_dictionary[0]);
    for (size_t i = 0; i < icount; i++) {
        if (!strcmp(str, item_dictionary[i].en)) {
            return item_dictionary[i].ru_cp1251;
        }
    }
    size_t mcount = sizeof(monster_dictionary) / sizeof(monster_dictionary[0]);
    for (size_t i = 0; i < mcount; i++) {
        if (!strcmp(str, monster_dictionary[i].en)) {
            return monster_dictionary[i].ru_cp1251;
        }
    }
    return str;
}

const char *
_3ds_i18n_file_alias(const char *fname)
{
    static char buf[64];
    size_t n;

    if (!fname || current_lang != NH_LANG_RU)
        return (const char *) 0;
    n = strlen(fname);
    if (n + 3 >= sizeof buf)
        return (const char *) 0;
    memcpy(buf, fname, n);
    buf[n++] = '.';
    buf[n++] = 'r';
    buf[n++] = 'u';
    buf[n] = '\0';
    return buf;
}
